# ---- 1) "Start fresh": clear the old data, keep every user login ----------
def clear_old_data(apps, schema_editor):
    get = lambda name: apps.get_model("wellness", name)
    get("ServiceUsage").objects.all().delete()
    get("WellnessBenefit").objects.all().delete()
    get("Employee").objects.all().delete()          # the logins themselves stay
    get("WellnessService").objects.all().delete()
    UserProfile = get("UserProfile")
    UserProfile.objects.update(company=None)
    for profile in UserProfile.objects.all():
        profile.roles.clear()
    get("Company").objects.all().delete()
    get("Role").objects.all().delete()               # old fixed roles


