def create_permissions_and_roles(apps, schema_editor):
    Permission = apps.get_model("wellness", "Permission")
    Role = apps.get_model("wellness", "Role")
    for code, name, description, area in PERMISSIONS:
        Permission.objects.update_or_create(
            code=code, defaults={"name": name, "description": description, "area": area}
        )
    for code, name, description, is_company_role, perms in ROLES:
        role, _ = Role.objects.update_or_create(
            code=code,
            defaults={"name": name, "description": description,
                      "is_company_role": is_company_role, "is_system": True},
        )
        role.permissions.set(Permission.objects.filter(code__in=perms))


